(()=>{if(window.__timingBoardProbe)return;const probe=window.__timingBoardProbe={records:[],lastClick:null,pending:new WeakSet(),seen:new WeakSet()};function current(){const id=location.pathname.split('/tasks/')[1]||new URLSearchParams(location.search).get('taskId');if(!id||!location.pathname.startsWith('/fcs/progress/board'))return null;const section=document.querySelector('[data-sewing-delivery-sla-detail]');if(section&&section.innerText.includes('交付时效'))return{kind:'progress',id,element:section};if(location.pathname.includes('/tasks/')){const nav=document.querySelector('button[data-progress-action="switch-task-tab"][data-tab="progress"]');if(nav&&document.body.innerText.includes(id)&&document.body.innerText.includes('任务详情'))return{kind:'detail',id,element:nav.closest('main')||nav.parentElement};return null;}const link=Array.from(document.querySelectorAll('a')).find(a=>a.textContent.trim()===id&&a.getAttribute('href')?.includes('/fcs/progress/board/tasks/'));if(link)return{kind:'list',id,element:link.closest('tr')||link.parentElement};return null;}function check(){const target=current();if(!target||probe.pending.has(target.element)||probe.seen.has(target.element))return;probe.pending.add(target.element);const beforePath=location.href;const beforeClick=probe.lastClick;const imgs=Array.from(document.querySelectorAll('img'));Promise.all(imgs.map(i=>i.decode())).then(()=>requestAnimationFrame(()=>requestAnimationFrame(()=>{probe.pending.delete(target.element);if(!target.element.isConnected||beforePath!==location.href)return;probe.seen.add(target.element);probe.records.push({kind:target.kind,id:target.id,url:location.href,readyAtMs:performance.now(),click:beforeClick,text:target.element.innerText,images:imgs.map(i=>({src:i.currentSrc,ok:i.complete&&i.naturalWidth>0})),viewport:{width:innerWidth,height:innerHeight},scripts:Array.from(document.querySelectorAll('script[src]')).map(i=>i.src)});}))).catch(e=>{probe.error=String(e)});}const observer=new MutationObserver(check);observer.observe(document,{childList:true,subtree:true});probe.observer=observer;probe.clickListener=e=>{const target=e.target?.closest?.('[data-progress-action],a');if(target){probe.lastClick={atMs:performance.now(),action:target.getAttribute('data-progress-action'),tab:target.getAttribute('data-tab'),href:target.getAttribute('href'),text:target.innerText};}};document.addEventListener('click',probe.clickListener,true);check();probe.stop=()=>{observer.disconnect();document.removeEventListener('click',probe.clickListener,true);delete window.__timingBoardProbe;};})()